{"path": "/tmp/sv-3aa077f139804417b4fb914e6377eff2/Components/Chat/ChatPage.razor", "file_text": "@page "/chat"
@namespace sv_3aa077f139804417b4fb914e6377eff2.Components.Chat
@rendermode InteractiveServer
@using sv_3aa077f139804417b4fb914e6377eff2.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(_threadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannelId"
                    OnChannelSelected="SelectChannel" />

    @if (_activeChannel is not null)
    {
        <MessageArea ChannelName="@_activeChannel.Name"
                     ChannelDescription="@_activeChannel.Description"
                     Messages="_messages"
                     ThreadSummaries="_threadSummaries"
                     IsLoadingMore="_isLoadingMore"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage"
                     OnLoadMore="LoadMoreMessages" />
    }

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];
    private List<Message> _threadReplies = [];
    private Channel? _activeChannel;
    private int _activeChannelId;
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private bool _isLoadingMore;
    private int _messageSkip;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        _activeChannel = channel;
        _activeChannelId = channel.Id;
        _messageSkip = 0;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messageSkip = _messages.Count;
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Update unread count locally
        var idx = _channels.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
        {
            _channels[idx] = channel with { UnreadCount = 0 };
        }

        BuildThreadSummaries();
    }

    private async Task LoadMoreMessages()
    {
        if (_isLoadingMore || _activeChannel is null) return;
        _isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _messageSkip, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _messageSkip += older.Count;
            BuildThreadSummaries();
        }
        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_activeChannel.Id, content, null);
        _messages.Add(msg);
        _messageSkip++;
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private async Task CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
        await Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _activeChannel is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update thread summary
        var existing = _threadSummaries.FirstOrDefault(t => t.RootMessageId == _threadRootMessage.Id);
        if (existing is not null)
        {
            _threadSummaries.Remove(existing);
            _threadSummaries.Add(existing with { ReplyCount = existing.ReplyCount + 1, LastReplyAt = reply.SentAt });
        }
        else
        {
            _threadSummaries.Add(new ThreadSummary(_threadRootMessage.Id, 1, reply.SentAt));
        }
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Optimistically update the local message
        var msg = _messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (msg is not null)
        {
            var reaction = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (reaction is not null)
            {
                reaction.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
        }
    }

    private void BuildThreadSummaries()
    {
        // Build thread summaries from messages that are replies
        var replyGroups = _messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value);

        _threadSummaries = replyGroups
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
    }
}
"}

