toolArgs.file_text:
.chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
}

.chat-layout.thread-open {
    grid-template-columns: 20% 1fr 25%;
}

/* Channel Sidebar */
::deep .channel-sidebar {
    background: #2b2d31;
    color: #b5bac1;
    padding: 1rem 0;
    overflow-y: auto;
    border-right: 1px solid #1e1f22;
}

::deep .sidebar-title {
    padding: 0 1rem;
    margin: 0 0 0.75rem;
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #949ba4;
}

::deep .channel-item {
    display: flex;
    flex-direction: column;
    padding: 0.5rem 1rem;
    cursor: pointer;
    border-radius: 4px;
    margin: 0 0.5rem;
    position: relative;
}

::deep .channel-item:hover {
    background: #35373c;
}

::deep .channel-item.active {
    background: #404249;
    color: #fff;
}

::deep .channel-name {
    font-weight: 500;
    font-size: 0.9375rem;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #949ba4;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    position: absolute;
    right: 0.75rem;
    top: 50%;
    transform: translateY(-50%);
    background: #f23f43;
    color: #fff;
    font-size: 0.6875rem;
    font-weight: 700;
    padding: 0.125rem 0.375rem;
    border-radius: 9999px;
    min-width: 1.25rem;
    text-align: center;
}

/* Message Area */
::deep .message-area {
    display: flex;
    flex-direction: column;
    background: #313338;
    color: #dbdee1;
    overflow: hidden;
}

::deep .message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

::deep .message-area-header p {
    margin: 0.25rem 0 0;
    font-size: 0.8125rem;
    color: #949ba4;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

::deep .loading-indicator {
    text-align: center;
    color: #949ba4;
    font-size: 0.8125rem;
    padding: 0.5rem;
}

::deep .message-item {
    padding: 0.5rem;
    border-radius: 4px;
    position: relative;
}

::deep .message-item:hover {
    background: #2e3035;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

::deep .message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9375rem;
}

::deep .message-time {
    font-size: 0.75rem;
    color: #949ba4;
}

::deep .message-content {
    margin-top: 0.25rem;
    font-size: 0.9375rem;
    line-height: 1.4;
}

::deep .message-reactions {
    display: flex;
    gap: 0.25rem;
    margin-top: 0.375rem;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.125rem 0.375rem;
    font-size: 0.8125rem;
    cursor: pointer;
}

::deep .reaction-badge:hover {
    border-color: #5865f2;
}

::deep .thread-link {
    font-size: 0.8125rem;
    color: #00a8fc;
    cursor: pointer;
    margin-top: 0.25rem;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.125rem;
}

::deep .action-btn {
    background: transparent;
    border: none;
    color: #b5bac1;
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    cursor: pointer;
    border-radius: 3px;
}

::deep .action-btn:hover {
    background: #3f4147;
    color: #fff;
}

::deep .emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.25rem;
    display: flex;
    gap: 0.25rem;
}

::deep .emoji-option {
    cursor: pointer;
    font-size: 1.25rem;
    padding: 0.125rem;
    border-radius: 3px;
}

::deep .emoji-option:hover {
    background: #3f4147;
}

/* Message Input */
::deep .message-input {
    display: flex;
    align-items: flex-end;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid #3f4147;
}

::deep .message-input textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    color: #dbdee1;
    padding: 0.625rem 1rem;
    font-size: 0.9375rem;
    resize: none;
    font-family: inherit;
    outline: none;
}

::deep .message-input textarea::placeholder {
    color: #6d6f78;
}

::deep .send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 4px;
    padding: 0.5rem 1rem;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
}

::deep .send-btn:hover {
    background: #4752c4;
}

::deep .send-btn:disabled {
    background: #4752c4;
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
::deep .thread-panel {
    display: flex;
    flex-direction: column;
    background: #2b2d31;
    border-left: 1px solid #1e1f22;
    color: #dbdee1;
    overflow: hidden;
}

::deep .thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

::deep .close-btn {
    background: transparent;
    border: none;
    color: #b5bac1;
    font-size: 1.25rem;
    cursor: pointer;
    padding: 0.25rem;
    border-radius: 3px;
}

::deep .close-btn:hover {
    background: #3f4147;
    color: #fff;
}

::deep .thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    background: #232428;
}

::deep .thread-root-message .message-author {
    font-size: 0.8125rem;
}

::deep .thread-root-message .message-content {
    font-size: 0.875rem;
    color: #949ba4;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

::deep .thread-reply {
    padding: 0.375rem 0;
}

